// Evaluate every alert rule against the freshly collected metrics.
// Returns one item per FIRING alert (empty array if all green).

const m = $items('Latest Metrics Snapshot').all[0]?.json || {};
const totals = m.totals || {};
const perWorkflow = m.per_workflow || [];

const hostMetricsRaw = $items('Node Exporter (CPU/Mem)').all[0]?.json?.data || '';
const hmText = typeof hostMetricsRaw === 'string' ? hostMetricsRaw : JSON.stringify(hostMetricsRaw || {});
const cpuMatch = hmText.match(/node_cpu_seconds_total\{mode="idle"\}\s+([\d.]+)/g) || [];
const memTotalMatch = hmText.match(/node_memory_MemTotal_bytes\s+(\d+)/);
const memAvailMatch = hmText.match(/node_memory_MemAvailable_bytes\s+(\d+)/);
let cpuUsagePct = null;
let memUsagePct = null;
if (memTotalMatch && memAvailMatch) {
  const total = parseInt(memTotalMatch[1], 10);
  const avail = parseInt(memAvailMatch[1], 10);
  memUsagePct = total ? ((total - avail) / total) * 100 : null;
}

const activeWorkflows = ($items('List Active Workflows').all[0]?.json?.data || []).filter(w => w.active === true);

const firing = [];
const now = new Date();

// Rule 1: workflow failure rate > 10% in 1h
if (typeof totals.failure_rate_1h_pct === 'number' && totals.failure_rate_1h_pct > 10 && totals.executions_1h >= 10) {
  firing.push({
    rule_id: 'WF_FAILURE_RATE_HIGH',
    severity: totals.failure_rate_1h_pct > 25 ? 'critical' : 'warning',
    message: `n8n failure rate is ${totals.failure_rate_1h_pct.toFixed(1)}% over the last hour (threshold: 10%)`,
    details: { failure_rate_pct: totals.failure_rate_1h_pct, executions_1h: totals.executions_1h, errors_1h: totals.executions_error_1h }
  });
}

// Rule 2: any workflow avg execution time > 5 min
for (const w of perWorkflow) {
  if (w.avg_duration_ms_24h > 300000) {
    firing.push({
      rule_id: 'WF_SLOW_EXECUTION',
      severity: 'warning',
      message: `Workflow "${w.workflow_name}" avg execution time is ${(w.avg_duration_ms_24h / 1000 / 60).toFixed(1)} min (threshold: 5 min)`,
      details: { workflow_id: w.workflow_id, workflow_name: w.workflow_name, avg_duration_ms: w.avg_duration_ms_24h }
    });
  }
}

// Rule 3: queue depth > 100
if (typeof totals.queue_depth === 'number' && totals.queue_depth > 100) {
  firing.push({
    rule_id: 'N8N_QUEUE_DEPTH_HIGH',
    severity: totals.queue_depth > 500 ? 'critical' : 'warning',
    message: `n8n queue depth is ${totals.queue_depth} (threshold: 100)`,
    details: { queue_depth: totals.queue_depth }
  });
}

// Rule 4: active workflow not executed in 24h (expected to)
for (const w of activeWorkflows) {
  const wfMetrics = perWorkflow.find(p => p.workflow_id === w.id);
  if (!wfMetrics || wfMetrics.total_24h === 0) {
    // Skip workflows that are explicitly marked as on-demand (no schedule)
    const isScheduled = (w.nodes || []).some(n => n.type && n.type.includes('scheduleTrigger'));
    if (isScheduled) {
      firing.push({
        rule_id: 'WF_NOT_EXECUTED_24H',
        severity: 'warning',
        message: `Scheduled workflow "${w.name}" has not executed in the last 24 hours`,
        details: { workflow_id: w.id, workflow_name: w.name }
      });
    }
  }
}

// Rule 5: n8n CPU > 80%
if (cpuUsagePct !== null && cpuUsagePct > 80) {
  firing.push({
    rule_id: 'N8N_CPU_HIGH',
    severity: cpuUsagePct > 95 ? 'critical' : 'warning',
    message: `n8n instance CPU usage is ${cpuUsagePct.toFixed(1)}% (threshold: 80%)`,
    details: { cpu_usage_pct: cpuUsagePct }
  });
}

// Rule 6: n8n memory > 80%
if (memUsagePct !== null && memUsagePct > 80) {
  firing.push({
    rule_id: 'N8N_MEMORY_HIGH',
    severity: memUsagePct > 95 ? 'critical' : 'warning',
    message: `n8n instance memory usage is ${memUsagePct.toFixed(1)}% (threshold: 80%)`,
    details: { mem_usage_pct: memUsagePct }
  });
}

return firing.length ? firing.map(alert => ({ json: { ...alert, evaluated_at: now.toISOString(), source: 'n8n-alert-rules' } })) : [{ json: { rule_id: 'NONE', severity: 'ok', message: 'All alert rules passing', evaluated_at: now.toISOString() } }];

